using BlaxtorGym.src.BlaxtorGym.Application.DTOs; using BlaxtorGym.src.BlaxtorGym.Domain.Entities; using BlaxtorGym.src.BlaxtorGym.Domain.Interfaces;
namespace BlaxtorGym.src.BlaxtorGym.Application.Services;
public class BitacoraService { private readonly IBitacoraRepository _repository; public BitacoraService(IBitacoraRepository repository) => _repository = repository; public async Task RegistrarAsync(int usuarioId, string accion, string entidad, int? entidadId, string? descripcion) { if (usuarioId <= 0) throw new ArgumentException("El usuario es obligatorio."); if (string.IsNullOrWhiteSpace(accion)) throw new ArgumentException("La acción es obligatoria."); if (string.IsNullOrWhiteSpace(entidad)) throw new ArgumentException("La entidad es obligatoria."); await _repository.AgregarAsync(new BitacoraCambio { UsuarioId = usuarioId, Accion = accion.Trim().ToUpperInvariant(), Entidad = entidad.Trim(), EntidadId = entidadId, Descripcion = string.IsNullOrWhiteSpace(descripcion) ? null : descripcion.Trim() }); } public async Task<List<BitacoraCambioDto>> ObtenerAsync(DateTime? i, DateTime? f, string? a, string? e, int? u) { if (i.HasValue && f.HasValue && i.Value.Date > f.Value.Date) throw new ArgumentException("La fecha inicial no puede ser posterior a la fecha final."); a = Filtro(a)?.ToUpperInvariant(); e = Filtro(e); var l = await _repository.ObtenerAsync(i, f, a, e, u); return l.Select(x => new BitacoraCambioDto { Id = x.Id, FechaHora = x.FechaHora, UsuarioId = x.UsuarioId, Usuario = x.Usuario?.NombreCompleto ?? string.Empty, Accion = x.Accion, Entidad = x.Entidad, EntidadId = x.EntidadId, Descripcion = x.Descripcion ?? string.Empty }).ToList(); } private static string? Filtro(string? v) => string.IsNullOrWhiteSpace(v) || string.Equals(v.Trim(), "Todas", StringComparison.OrdinalIgnoreCase) ? null : v.Trim(); }
